/*
 * A142187  Primes congruent to 11 mod 40.
 * https://oeis.org/A142187
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   not stated
 * Range:     u8 n <= 4, u16 n <= 318, u32 n <= 331, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   is_prime_big
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence of primes congruent to 11 mod 40.  Generated by testing
   integers of the form 40*k + 11 and keeping those that are prime. */

#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include "../utils/is_prime_big.h"

seq_t a(idx_t n)
{
    /* Static cache of discovered primes. */
    static seq_t *cache = NULL;        /* array of primes */
    static size_t cap   = 0;           /* current capacity of array */
    static size_t len   = 0;           /* number of primes stored */
    static seq_t next_candidate = 11;  /* next number of the form 40*k+11 */

    /* OEIS offset starts at 1; n==0 is undefined – return 0. */
    if (n == 0)
        return 0;

    /* Grow the cache until we have at least n primes. */
    while (len < n)
    {
        if (is_prime_big(next_candidate))
        {
            if (len >= cap)
            {
                size_t new_cap = (cap ? cap * 2 : 16);
                seq_t *tmp = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
                if (!tmp)            /* allocation failed */
                    exit(EXIT_FAILURE);
                cache = tmp;
                cap   = new_cap;
            }
            cache[len++] = next_candidate;
        }
        next_candidate += 40ULL;  /* advance to next candidate of form 40*k+11 */
    }

    return cache[n - 1];
}
